changeSet.sql:
CREATE TABLE IF NOT EXISTS votality_asignaciones_encuestadores (
    id BIGSERIAL PRIMARY KEY,
    encuestador_id UUID NOT NULL REFERENCES votality_usuarios(id) ON DELETE CASCADE,
    campana_id UUID NOT NULL REFERENCES votality_campanas(id) ON DELETE CASCADE,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_asignacion TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_asignacion_encuestador_campana UNIQUE (encuestador_id, campana_id)
);

CREATE INDEX IF NOT EXISTS idx_asig_encuestador ON votality_asignaciones_encuestadores(encuestador_id);
CREATE INDEX IF NOT EXISTS idx_asig_campana ON votality_asignaciones_encuestadores(campana_id);

CREATE TABLE IF NOT EXISTS votality_encuestas (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    campana_id UUID NOT NULL REFERENCES votality_campanas(id) ON DELETE CASCADE,
    encuestador_id UUID REFERENCES votality_usuarios(id) ON DELETE SET NULL,
    nombre_completo VARCHAR(200) NOT NULL,
    direccion VARCHAR(250) NOT NULL,
    coordenadas geometry(Point, 4326) NOT NULL,
    respuestas_personalizadas JSONB NOT NULL DEFAULT '{}'::jsonb,
    creado_el TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_campana_coordenadas_pin UNIQUE (campana_id, coordenadas)
);

CREATE INDEX IF NOT EXISTS idx_encuesta_coordenadas_gist 
ON votality_encuestas USING GIST (coordenadas);

CREATE INDEX IF NOT EXISTS idx_encuesta_campana_fecha 
ON votality_encuestas (campana_id, creado_el);

CREATE INDEX IF NOT EXISTS idx_encuesta_nombre 
ON votality_encuestas (nombre_completo);

-- Disparador DDL/DML de inmutabilidad estricta
CREATE OR REPLACE FUNCTION fn_prevent_encuesta_update()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'Regla Multi-Tenant Violada: Los registros de encuesta en votality_encuestas son inmutables tras su guardado para auditoría electoral.';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_encuestas_prevent_update ON votality_encuestas;
CREATE TRIGGER trg_encuestas_prevent_update
BEFORE UPDATE ON votality_encuestas
FOR EACH ROW
EXECUTE FUNCTION fn_prevent_encuesta_update();

rollback.sql:
DROP TRIGGER IF EXISTS trg_encuestas_prevent_update ON votality_encuestas;
DROP FUNCTION IF EXISTS fn_prevent_encuesta_update();
DROP TABLE IF EXISTS votality_encuestas;
DROP TABLE IF EXISTS votality_asignaciones_encuestadores;
DROP TABLE IF EXISTS votality_campanas;
DROP TABLE IF EXISTS votality_usuarios;
DROP TABLE IF EXISTS votality_tipos_planes;
